 [{"type": "course", "course_id": "CRS-ISO-101", "target_id": "CRS-ISO-101", "required": False, "reason": T("Recommended, not mandatory: the structure lesson makes this course easier.", "موصى به وليس إلزاميًا: درس البنية يسهّل هذه الدورة.")},
  {"type": "knowledge", "target_id": "KA-005", "required": False, "reason": T("Orientation article", "مقالة تمهيدية")}],
 [("Identify the parts of a standard and what each part is for.", "تحديد أجزاء المواصفة والغرض من كل جزء."),
  ("Separate requirements from notes, examples and informative annexes.", "الفصل بين المتطلبات والملاحظات والأمثلة والملاحق الإرشادية."),
  ("Interpret shall, should, may and can correctly in both languages.", "تفسير shall وshould وmay وcan تفسيرًا صحيحًا باللغتين."),
  ("Convert a requirement into process controls, evidence, an audit question and a potential finding.", "تحويل المتطلب إلى ضوابط عمليات وأدلة وسؤال تدقيق وملاحظة محتملة.")],
 ("A focused course on reading a standard as a professional: its anatomy, the verbal forms that separate obligation from advice, and a repeatable chain from requirement to objective evidence.",
  "دورة مركزة لقراءة المواصفة قراءة مهنية: تشريحها، وصيغ الأفعال التي تفصل الإلزام عن النصيحة، وسلسلة قابلة للتكرار من المتطلب إلى الدليل الموضوعي."),
 ("Misreading a ‘should’ as a ‘shall’ creates unnecessary bureaucracy; misreading a note as a requirement creates false findings.", "قراءة «should» على أنها «shall» تُنشئ بيروقراطية غير ضرورية، وقراءة الملاحظة على أنها متطلب تُنتج ملاحظات تدقيق خاطئة."),
 ("Core skill for implementers and auditors; used daily in gap analysis and audit preparation.", "مهارة أساسية للمطبقين والمدققين، تُستخدم يوميًا في تحليل الفجوات والتحضير للتدقيق."),
